<script setup lang="ts">
import { Form } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
type U={id:number;name:string;email:string;phone?:string;is_active:boolean}; type R={id:number;name:string;email:string;phone?:string;requester?:{name:string};createdAt:string};
const p=defineProps<{role:string;roleLabel:string;users:{data:U[]};pendingRequests:R[]}>(); const open=ref(false); const reject=ref<R|null>(null); const desc=computed(()=>({sales:'Bán hàng và vận hành đơn hàng.',technical:'Sản phẩm, tồn kho và hỗ trợ kỹ thuật.',customer_service:'Chăm sóc khách hàng và hỗ trợ sau bán.'}[p.role]??''));
