ype="password" minlength="8" required/><label>Mật khẩu xác thực quản trị</label><input name="admin_password" type="password" required/><div v-if="errors" class="text-danger small">{{Object.values(errors)[0]}}</div><footer><button type="button" class="btn btn-light" @click="open=false">Hủy</button><button class="btn btn-primary" :disabled="processing">Xác nhận</button></footer></Form></section></div><div v-if="reject" class="overlay" @click.self="reject=null"><section class="modal"><h2>Từ chối yêu cầu</h2><Form :action="`/admin/backoffice-requests/${reject.id}/reject`" method="patch" @success="reject=null"><label>Lý do</label><textarea name="reason" rows="3"/><footer><button type="button" class="btn btn-light" @click="reject=null">Hủy</button><button class="btn btn-danger">Từ chối</button></footer></Form></section></div></div></template>
